const picker = (() => {
            if (!currencyTrackPicking) return '';
            const names = (typeof knownCharacterNames === 'function') ? knownCharacterNames() : [];
            const isOn = (nm) => tracked.some(t => String(t).replace(/\s+/g, '').toLowerCase() === String(nm).replace(/\s+/g, '').toLowerCase());
            const rowOf = (nm) => {
                const on = isOn(nm);
