            };
            pageListRenderers['currencyTrackPick'] = () => {
                const shown = pageSearchItems('currencyTrackPick', names.map(nm => ({ name: nm })));
                pageListCounts['currencyTrackPick'] = { shown: shown.length, total: names.length };
                if (!names.length) return '<div class="ftt-empty">「角色」大类暂无已知角色：先运行「AI 摘要」生成角色档案，或在角色页添加角色。</div>';
